# Keys: (pfad_oder_basename, "Feld#c:CODE") bzw. "Feld#r:ZEILE" (Quellzeile ohne Code).

DE_IMA_EM = {
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:02000201_0'): 'Brrr. Was für eine eisige Gegend ist das?\nIch konnte nicht mal eine Handbreit\nvor meinem Gesicht sehen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:02000201_1'): 'Dieser Schneesturm wird zweifellos auch die\nDämonen in ihre Höhlen treiben.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:02000201_2'): 'Wir können noch eine Weile nicht jagen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:02000201_3'): 'Willkommen zurück, Lady Sakuna und Tama.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:02000201_4'): 'Zieht bitte passende Kleidung an und\nwärmt euch am Feuer.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04000201_0'): 'Ah, ihr wart also im Haus.\nLady Sakuna. Tama. Ich habe beunruhigende Nachrichten...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04000201_1'): 'Was nun? Wir sind gerade erst nach Hause gekommen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04000201_10'): 'Wenn wir nicht beobachten, was auf dieser\nInsel geschieht, könnten wir ins Nachteil geraten,\nwenn die Lage außer Kontrolle gerät.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04000201_11'): 'Stimmt. Zum südlichen Vulkan also.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04000201_2'): 'Im Fluss aus dem südlichen Vulkan schwammen\neine Menge tote Fische.\nDas Wasser sieht und riecht nach Gift.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04000201_3'): 'Glücklicherweise beziehen unsere Felder ein anderes\nWasser, sodass uns das nicht direkt betrifft.\nTrotzdem mache ich mir Sorgen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04000201_4'): 'Gift aus dem Vulkan, sagst du?\nHat Schwefel das Wasser verseucht?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04000201_5'): 'Wenn es unsere Felder nicht betrifft, was\nkümmert das uns? Wir können uns nicht um einen\nVulkan sorgen, der ganz normal seinen Gang geht.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04000201_6'): 'E-E-Entsetzlich! Diesmal stecken wir tief drin!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04000201_7'): 'Uuugh. Steckt heute etwas in der Luft?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04000201_8'): 'Im Westen ist eine Horde Dämonen aufgetaucht,\nund sie steuern auf den Vulkan zu!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04000201_9'): 'Keine Ruhe für die Bösen, was?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010101_0'): 'Dieses Jahres Ernte war wirklich herrlich!\nZu denken, dass wir einst so verzweifelt rangen...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010101_1'): 'Ja! Die Kappa haben sich besonders hervorgetan.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010101_10'): 'Wir müssen dem Reis eine Marke geben.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010101_11'): 'Eine Marke? Das könnte schwierig werden.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010101_12'): 'Lasst uns alle zusammenholen. Es fällt\nvielleicht leichter, auf eine Idee zu kommen,\nwenn wir die Köpfe zusammenstecken.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010101_2'): 'Ihre Schuld ist bestimmt völlig beglichen.\nVielleicht schenke ich ihnen ein Zeichen des Danks.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010101_3'): 'Ich glaube, Kappa mögen Gurken.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010101_4'): 'Gurken, sagst du?\nDie, die auf dieser Insel wachsen, sind zu\nbitter, um sie verschenken zu können.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010101_5'): 'Warum verkauft ihr nicht euren überschüssigen Reis\nund kauft Gurken aus der Hauptstadt?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010101_6'): 'Ah! Eine großartige Idee.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010101_7'): 'Ich werde stärker, wenn der Reis geschält wird,\nwenn wir also mehr haben, als wir essen können,\nist Verkauf des Übrigs eine kluge Option.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010101_8'): 'Lady Kamuhitsuki wird sich bestimmt auch freuen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010101_9'): 'Ich werde meinerseits mich mit unseren Leuten\nin der Hauptstadt in Verbindung setzen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010301_0'): 'Oh, willkommen zurück.\nIhr habt einen Gast.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010301_1'): 'Hm? Ein Gott aus der Hauptstadt? Was will der?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010301_2'): 'Nun... ich bin mit ihrer Mundart nicht vertraut,\nalso kann ich leider nichts sagen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010301_3'): 'Oho. Es ist schon eine Weile her, alter Freund.\nWie hast du dich gehalten?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010301_4'): 'Diese hier sind gewandte Beschützer,\ndoch das Sprechen ist weniger ihre Stärke.\nIch werde übersetzen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010301_5'): '...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010301_6'): 'Das ging völlig an mir vorbei.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010301_7'): 'Es scheint etwas in der Hauptstadt passiert zu sein.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_0'): 'Eine neue Reismarke konkurriert mit unserer\nin der Hauptstadt, sagst du?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_1'): 'Ho... Das ist interessant.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_10'): 'Mmm... Das ist... mehr als nur ähnlich.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_11'): 'Das sind doch unsere Verehrten Ähren, oder?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_12'): 'Scheint so.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_13'): 'Was soll das bedeuten?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_14'): 'Unserer ist köstlich, aber...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_15'): 'Dieses Los hinterlässt einen... eigenartigen Nachgeschmack.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_16'): 'Genau. Du hast es also auch bemerkt.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_17'): 'Wer diesen Reis kauft, ist getroffen von seinem\nNachgeschmack, der ihn zwingt, nur noch ihn zu\nessen und keine andere Sorte mehr.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_18'): 'Das klingt langsam bedrohlich...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_19'): 'Samen, Boden und Wasser prägen alle den\nGeschmack von Reis. Es ist also unmöglich,\nden gleichen Geschmack an anderen Orten zu erzeugen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_2'): 'Weniger „interessant", vielmehr unglaublich.\nDas Erhabene Reich erntet weiterhin dieselben\nminderwertigen Ernten wie eh und je.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_20'): 'Mit anderen Worten: Dieser Reis sind unsere\nVerehrten Ähren, auf geheimnisvolle Weise verändert.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_21'): 'Aus der Nähe sind winzige Körner anderer Reissorten\ndarin gemischt. Da muss ein Trick dahinter stecken.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_22'): 'Wer würde so etwas Hinterhältiges tun?!\nWer hat diesen Reis hergestellt?!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_23'): '...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_24'): '...Prinzessin Kokorowa?!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_3'): 'Schon lange bauen die Erntegötter nur noch\nBohnen oder Gerste an, mit gerade genug Reis,\num den Zehnt von Lady Kamuhitsuki zu erfüllen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_4'): 'Genau deshalb konnten sie ihren Rang allein\ndurch das Opfern der hochwertigen Reisvorräte\nihrer Mutter behaupten.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_5'): 'L-Lasst uns über vergangene Verfehlungen hinwegsehen...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_6'): 'Wie auch immer, ich kann nicht begreifen, wie ihr\nReis mit unseren Verehrten Ähren konkurrieren soll.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_7'): 'Ist das der gemeinte Reis?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_8'): 'Hey, Großer. Komm her und koch ihn.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:04010302_9'): 'Hmmm... *mampf* *mampf*',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_0'): 'Was zum-- Ihr da!\nSofort erklärt euch!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_1'): 'Oh, Göttin... Willkommen zurück.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_10'): 'Nein! Das erlaube ich nicht!\nEin Dämon ist ein Dämon!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_11'): 'Die Prinzessin hat recht.\nDas ist kein gewöhnliches Tier.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_12'): 'Dämonen sind durch und durch böse Wesen.\nSie strotzen vor Groll und können\nfeinere Begriffe wie Dankbarkeit nicht erfassen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_13'): 'Wenn ihr es nicht jetzt erledigt, weiß niemand,\nwas für ein Unglück noch kommen mag.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_14'): 'A-Aber... seine Wunden! In seinem Zustand doch--',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_15'): 'Waaaaah!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_16'): 'Ich habe doch schon unzählige Kaninchen getötet\nund für euch abgezogen, oder nicht?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_17'): 'Warum jetzt so gnädig...?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_18'): 'Ich weiß, es ist egoistisch von mir. Vielleicht\nsogar irrational. Aber ich kann es einfach nicht lassen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_19'): 'Ich bitte dich auch, Göttin. Bitte, rette ihn.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_2'): 'Yo.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_20'): 'Er zittert und kann kaum noch atmen.\nIch kann nicht einfach zusehen, wie man ihn tötet.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_21'): 'Ugh...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_22'): 'Du solltest ihn erledigen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_23'): 'Kinta!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_24'): 'Ein weiches Herz zu haben ist ja schön und so.\nAber es bringt nichts, wenn wir alle draufgehen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_25'): 'Ich... ich halte es nicht aus, wenn du so etwas\nsagst!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_26'): 'Hä...?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_27'): 'Aaagh!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_28'): 'Na gut! Aber sobald es wieder auf den Beinen ist,\nwerfen wir es raus und knallen die Tür zu!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_29'): 'Denk nicht daran, es hier als Haustier zu behalten!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_3'): 'Sag mir nicht „Yo"!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_30'): 'Prinzessin? Das ist inakzeptabel!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_31'): 'Ich sage es nicht noch einmal!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_32'): 'Sah-Sah!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_33'): 'Lady Sakuna!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_34'): 'Oh, Göttin!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_35'): 'Und du, törichter Samurai! Halt dein Schwert scharf.\nFalls etwas schiefgeht, liegt die Verantwortung,\nes zu töten, allein bei dir.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_36'): 'Ich gehe mal an die frische Luft--Luft, die\nnicht von törichtem Sentiment verseucht ist!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_37'): 'Prinzessin, warte doch!\nPrinzessin?!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_38'): 'Ugh. Alles Weicheier.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_4'): 'Während ich mein Leben riskierte, die Festung anzugreifen,\nwart ihr der Meinung, einen Dämonen\nwie ein Streunerkätzchen bei uns einzustellen?!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_5'): 'Wir haben ihn zusammengebrochen an einem\nder nahegelegenen Ernteplätze gefunden.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_6'): 'Er war voller tiefer Schnittwunden, also dachten\nwir, seine Kameraden hätten ihn aus irgendeinem\nGrund im Stich gelassen und sterben lassen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_7'): 'Eee, uuuh...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_8'): 'Er wirkte wirklich verängstigt. Wir konnten ihn\ndoch nicht einfach allein dort lassen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:05000102_9'): 'Sobald er wieder gehen kann, lassen wir ihn gehen.\nBis dahin bleibt er--',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_0'): 'Lange nicht gesehen, Katsura.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_1'): 'Warte!\nBitte, lass mich das übernehmen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_10'): 'Aber du bist gar kein Samurai!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_11'): 'Rrrgh...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_12'): 'Hör auf zu tun, als wärt ihr noch\nim Krieg.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_13'): 'Es stimmt, das Niedrige Reich war die Hölle.\nWeithin herrschten Hunger und Streit und säten\ndie Saat endloser Tragödien.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_14'): 'Selbst ich, ein Deserteur, kenne die Schande,\nauf dem Schlachtfeld zu scheitern und vom Feind\nverjagt zu werden. Euren Schmerz verstehe ich.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_15'): 'Aber... gerade deshalb solltet ihr jetzt\nin der Lage sein, Frieden zu finden.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_16'): 'Nachdem ihr eure dämonischen Kräfte verloren habt--',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_17'): 'Pffft... Hahaha...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_18'): 'Ihr habt alles falsch verstanden.\nVöllig, gänzlich, jämmerlich falsch.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_19'): 'Ich wusste es. Leute wie du...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_2'): 'Das heißt, äh...\nKommt hoch und isst etwas.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_20'): '...sind die Luft nicht wert, die ihr atmet!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_21'): 'DU warst derjenige, der ständig so tat,\nals wärst du etwas, was du nicht bist, betrügerischer Bauer.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_22'): 'Mrrrgh...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_23'): 'Tu es. Dann können wir vielleicht beide wieder\nwerden, was wir sein sollten.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_24'): 'Ein Samurai, der sich wie ein Samurai benimmt,\nund ein Bauer, ein Bauer.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_25'): 'Nein, das meine ich nicht--!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_26'): 'Aaawoo?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_27'): 'Kaimaru!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_28'): 'Pass auf. Keine komischen Bewegungen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_29'): 'Lange nicht gesehen, Kaimaru.\nErinnerst du dich an mich?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_3'): 'Diesen Ort mit eigenen Augen zu sehen, hat\nnur meinen Entschluss gefestigt. Du hast nicht verdient zu leben.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_30'): 'Aaah...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_31'): 'Ishimaru, diese Angelegenheit betrifft nur uns!\nLasst Kaimaru sofort los!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_32'): 'Oh, nein, nein, nein... Er gehört unbedingt DAZU.\nEr ist das lebendige Vermächtnis unseres\ngeliebten Chefs, oder nicht?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_33'): 'Mit dem Chef war es wirklich schade.\nIch wollte ihn auch nicht töten, weißt du.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_34'): 'Aber mit dieser starrköpfigen Hartnäckigkeit...\nEs war töten oder sterben.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_35'): 'Mit naivem Gerede wie dem da rettest du\nkeinen einzigen. Stimmt das, Kaimaru?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_36'): 'Aaah! Waaah!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_37'): 'Was ist das?\nKann er nicht mehr sprechen?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_38'): 'Was für ein Witz!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_39'): 'Kaimaru!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_4'): 'Ishimaru... Wir bloß...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_40'): 'Ishimaru, öffne die Augen!\nAuf dieser Insel gibt es keinen Krieg!\nHier verhungert niemand!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_41'): 'Welchen Grund hätten wir zu kämpfen?!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_42'): 'Hä? Was für Blödsinn redest du da?\nDU bist derjenige, der MIR im Weg war.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_43'): 'Räum mir den Weg. Für heute bin ich fertig.\nSo jämmerlich alles auch ist, ich habe meinen Stolz.\nSieht aus wie früher.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_44'): 'Ich komme so oft für dich, wie es nötig ist.\nGanz gleich, was ich tun muss.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_45'): 'Lasst Kaimaru frei.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_46'): 'Sagt er, mit der Hand am Griff seiner Klinge.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_47'): 'Siehst du nicht, was du zu tun hast?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_48'): 'Gah...?!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_49'): 'Was soll das--? Verdammt, lasst mich LOS!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_5'): 'Muss schon sagen, dieser Ort ist wirklich\nbeeindruckend, Katsura.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_50'): 'Kaimaru!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_51'): 'Ich verfolge ihn!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_52'): 'Kaimaru... Kaimaru! Hal durch!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_53'): 'Myrthe...!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_6'): 'Sieht aus, als hättet ihr hier ein Qualitätsprodukt.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_7'): 'Ah... Ja! Also selbst du kannst es erkennen?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_8'): 'Dann bedient euch nur!\nEin voller Bauch und eine gute Nacht\nbesänftigen selbst den wütendsten Zorn!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:06000401_9'): 'Haha... Der Samurai feiert die Armut.\nIch erniedrige mich nicht nur wegen des Essens.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_0'): 'Ugh...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_1'): 'Nnngh... Kein Weg...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_10'): 'Nur eine Rüge für den Bruch eines\nFamilienerbstücks? Ich denke, er wäre\nweit wütender als das.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_11'): 'Nun... ich kann sowieso kein Schwert führen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_12'): 'Doch gleich wie groß auch die Kluft zwischen uns ist,\nmein Vater macht mir immer noch Angst.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_13'): 'Es tut mir wirklich leid! Ich repariere es später,\ndamit du es wieder benutzen kannst!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_14'): 'Oho, du bist also ein geschickter Schmied geworden?\nGlorreich, Kinta!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_15'): 'H-Hör doch auf damit, willst du?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_16'): 'Oh? Oooh? Wirst du rot?\nDu wirst wirklich rot!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_17'): 'Nnngh! Verflucht seist du, Sakuna!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_18'): 'Was, sollen wir uns einen königlichen Kampf\nliefern? Halte dich bereit, du winziger Tunichtgut!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_19'): 'Hört! Auf! Sofort!',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_2'): 'S-Sollen wir vielleicht fragen?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_3'): 'Oh, Lady Sakuna. Und Kinta auch.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_4'): 'Heute Morgen habe ich entdeckt, dass mein Schwert\ngebrochen ist. Seht her. Ganz sauber abgesplittert.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_5'): 'Es sieht fast aus, als wäre es geschnitten worden.\nWahrhaft rätselhaft, meinst du nicht?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_6'): 'Ahaha...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_7'): 'E-Es tut mir leid. Es ist wahrscheinlich meine Schuld.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_8'): 'Was meinst du?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:07000303_9'): 'Ich verstehe. Wenn mein Vater davon Wind bekäme,\nwürde ich die Zurechtweisung meines Lebens bekommen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:08000501_0'): 'Es ist wie zuvor.\nSeine Seele ist fortgegangen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:08000501_1'): 'Wohin zieht es ihn diesmal?\nWessen Herz hat er verbunden?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:08000501_10'): 'Myrthe...',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:08000501_11'): 'Aber ich KANN glauben, dass sie zurückkehren.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:08000501_12'): 'Ich werde auch zu meinem Gott beten.\nDass Sakuna und Kaimaru zu uns zurückkehren.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:08000501_2'): 'Er sagt... er holt die Göttin zurück.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:08000501_3'): 'Ich verstehe. Lady Sakuna und Lord Tama sind\nschon eine Weile fort, also hat er seine Seele\nals Leuchtfeuer gesendet, um sie zurückzuführen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:08000501_4'): 'Mann, der ist echt nicht zu fassen.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:08000501_5'): 'Aber jetzt können wir nur ihm vertrauen und warten.\nSo wie er uns vertraut.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:08000501_6'): 'In der Tat, wir können nur beten.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:08000501_7'): 'Aber wir sind hier im Erhabenen Reich,\nwen sollen wir also anbeten?',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:08000501_8'): 'Zu Sakuna und Kaimaru, offensichtlich.\nDie sind doch auch Götter, weißt du.',
    ('Text/Event/Mura/Ima/EventMain.csvtxt', 'English#c:08000501_9'): 'Der Gott, an den ich glaube, ist ein anderer.',
}

